    if (!perPlan) { perPlan = new Map(); _prorateCache.set(plan, perPlan); }
    const key = asOf || '__null__';
    if (perPlan.has(key)) return perPlan.get(key);

    let v;
    const fd = Math.max(1, dI(plan.fs, plan.fe));
